// Package images pre-pulls every container image the installer needs, in
// parallel, right after k3s is ready — instead of serially inside each
// `helm upgrade --wait`.
//
// images.txt is generated by scripts/gen-images.sh from the pinned charts in
// internal/versions and the static manifests; it is embedded at build time.
package images

import (
	"bufio"
	"context"
	_ "embed"
	"fmt"
	"io"
	"log"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"time"
)

//go:embed images.txt
var imagesTxt string

// DefaultConcurrency is used when PrePull is called with concurrency < 1.
const DefaultConcurrency = 4

// MaxAttempts is how many times a single image pull is tried.
const MaxAttempts = 3

// Runner executes a command and returns its combined output. It is a package
// variable so tests can substitute a fake (no k3s required).
type Runner func(ctx context.Context, name string, args ...string) ([]byte, error)

// Run is the command runner used by PrePull.
var Run Runner = func(ctx context.Context, name string, args ...string) ([]byte, error) {
	return exec.CommandContext(ctx, name, args...).CombinedOutput()
}

// LogPath is where PrePull writes its progress log. If it cannot be opened the
// log is silently discarded.
var LogPath = "/var/log/platformctl/prepull.log"

// Backoff returns how long to wait before retry number attempt (1-based).
var Backoff = func(attempt int) time.Duration {
	return time.Duration(attempt) * 2 * time.Second
}

// Result reports what PrePull did. Failures are warnings: Helm pulls any
// missing image again when it installs the chart.
type Result struct {
	Pulled  []string
	Skipped []string
	Failed  map[string]error
}

// List returns the embedded image list: trimmed, without blanks or #comments,
// deduplicated, in file order.
func List() []string {
	return parse(imagesTxt)
}

func parse(s string) []string {
	var out []string
	seen := map[string]bool{}
	sc := bufio.NewScanner(strings.NewReader(s))
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" || strings.HasPrefix(line, "#") || seen[line] {
			continue
		}
		seen[line] = true
		out = append(out, line)
	}
	return out
}

// PrePull pulls List() plus extra (e.g. the tag-dependent platform-api and
// platform-portal images) with `k3s crictl pull`, at most concurrency at a
// time. Images already present (`k3s crictl inspecti` succeeds) are skipped;
// failed pulls are retried up to MaxAttempts with backoff. Cancelling ctx
// stops new work and aborts in-flight pulls. PrePull never panics on pull
// errors; they are returned in Result.Failed.
func PrePull(ctx context.Context, concurrency int, extra ...string) Result {
	if concurrency < 1 {
		concurrency = DefaultConcurrency
	}
	all := List()
	seen := map[string]bool{}
	for _, img := range all {
		seen[img] = true
	}
	for _, img := range extra {
		img = strings.TrimSpace(img)
		if img != "" && !seen[img] {
			seen[img] = true
			all = append(all, img)
		}
	}

	logger, closeLog := openLog()
	defer closeLog()
	start := time.Now()
	logger.Printf("pre-pull start: %d images, concurrency %d", len(all), concurrency)

	res := Result{Failed: map[string]error{}}
	var mu sync.Mutex
	jobs := make(chan string)
	var wg sync.WaitGroup
	for i := 0; i < concurrency; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for img := range jobs {
				skipped, err := pullOne(ctx, logger, img)
				mu.Lock()
				switch {
				case err != nil:
					res.Failed[img] = err
				case skipped:
					res.Skipped = append(res.Skipped, img)
				default:
					res.Pulled = append(res.Pulled, img)
				}
				mu.Unlock()
			}
		}()
	}

feed:
	for i, img := range all {
		select {
		case jobs <- img:
		case <-ctx.Done():
			mu.Lock()
			for _, rest := range all[i:] {
				res.Failed[rest] = ctx.Err()
			}
			mu.Unlock()
			break feed
		}
	}
	close(jobs)
	wg.Wait()

	sort.Strings(res.Pulled)
	sort.Strings(res.Skipped)
	logger.Printf("pre-pull done in %s: %d pulled, %d already present, %d failed",
		time.Since(start).Round(time.Second), len(res.Pulled), len(res.Skipped), len(res.Failed))
	return res
}

// pullOne returns skipped=true when the image is already present.
func pullOne(ctx context.Context, logger *log.Logger, img string) (bool, error) {
	if err := ctx.Err(); err != nil {
		return false, err
	}
	if _, err := Run(ctx, "k3s", "crictl", "inspecti", img); err == nil {
		logger.Printf("present  %s", img)
		return true, nil
	}
	var lastErr error
	for attempt := 1; attempt <= MaxAttempts; attempt++ {
		t0 := time.Now()
		out, err := Run(ctx, "k3s", "crictl", "pull", img)
		if err == nil {
			logger.Printf("pulled   %s (%s)", img, time.Since(t0).Round(100*time.Millisecond))
			return false, nil
		}
		lastErr = fmt.Errorf("crictl pull %s: %w: %s", img, err, strings.TrimSpace(string(out)))
		if ctx.Err() != nil {
			return false, ctx.Err()
		}
		logger.Printf("attempt %d/%d failed: %v", attempt, MaxAttempts, lastErr)
		if attempt == MaxAttempts {
			break
		}
		select {
		case <-time.After(Backoff(attempt)):
		case <-ctx.Done():
			return false, ctx.Err()
		}
	}
	logger.Printf("FAILED   %s", img)
	return false, lastErr
}

func openLog() (*log.Logger, func()) {
	discard := log.New(io.Discard, "", 0)
	if LogPath == "" {
		return discard, func() {}
	}
	if err := os.MkdirAll(filepath.Dir(LogPath), 0o755); err != nil {
		return discard, func() {}
	}
	f, err := os.OpenFile(LogPath, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
	if err != nil {
		return discard, func() {}
	}
	return log.New(f, "", log.LstdFlags), func() { _ = f.Close() }
}
